"""TaxOS story adapted from the owner's earlier portfolio, with evidence boundaries."""
from html import escape as e
from portfolio_layout import render, contact_cta
from taxos_visuals import personas, workflow, decisions, storyboard, guide


def taxos_case(project, next_project):
    def figure(name, caption):
        return f'''<figure class="case-figure"><button class="case-image" type="button" data-image="/reference/profile/taxos/{name}.png" data-title="TaxOS — {e(caption)}" aria-label="Enlarge TaxOS design"><img src="/reference/profile/taxos/{name}.png" alt="{e(caption)}" loading="lazy"><span>take a closer look ↗</span></button><figcaption>{e(caption)}</figcaption></figure>'''
    content = f'''<div class="section-rule"><a href="/projects">← all work</a><span>[Payvio / TaxOS]</span></div>
<header class="case-header invoice-header"><p class="eyebrow">AI PRODUCTS · PRODUCT DESIGN · 2025–2026</p><h1 class="sticker">Less chasing.<br>More preparing.</h1><p class="case-subtitle">TaxOS · AI-assisted tax preparation for Payvio</p><p class="invoice-deck">A client has the files. A CPA needs the facts. I designed the workflow that connects them.</p><dl class="case-facts"><div><dt>My role</dt><dd>Product designer</dd></div><div><dt>Client</dt><dd>Payvio Ltd.</dd></div><div><dt>Timeline</dt><dd>2025–2026</dd></div></dl></header>
{guide()}
{storyboard()}
<figure class="case-hero"><img src="/reference/profile/taxos/overview.png" alt="TaxOS product design overview from the original portfolio" fetchpriority="high"></figure>
<nav class="chapter-nav" aria-label="Case study chapters"><a href="#brief-title">At a glance</a><a href="#problem">The problem</a><a href="#research">Meet the people</a><a href="#decisions">Design decisions</a><a href="#prototype">Prototype</a><a href="#iteration">Iteration</a><a href="#outcomes">Outcomes</a></nav>
<section class="case-brief" aria-labelledby="brief-title"><h2 id="brief-title">The project at a glance</h2><dl><div><dt>The problem</dt><dd>Document collection and manual workpapers slowed offshore teams preparing US tax returns.</dd></div><div><dt>My contribution</dt><dd>Designed the CPA workspace and client portal. Built a functional prototype with mock tax data to test workflows before production.</dd></div><div><dt>Product ambition</dt><dd>Reduce manual preparation work by at least 50%. This was the project goal, not an established result.</dd></div></dl><details class="evidence-note"><summary>Scope and evidence notes</summary><p>This story and its screenshots come from my earlier TaxOS case study. Research, domain expertise, engineering and commercial results were team efforts. Reported outcomes are retained below with their missing measurement context.</p></details></section>
<section class="invoice-chapter" id="problem"><p class="eyebrow">01 / THE BOTTLENECK</p><h2>The work started long before the return.</h2>{workflow()}</section>
<section class="invoice-chapter" id="research"><p class="eyebrow">02 / DISCOVERY</p><h2>Two sides of the same handoff.</h2>{personas()}<p class="chapter-copy">Discovery pointed to a shared bottleneck: collecting and organizing information before tax preparation could begin.</p><details class="evidence-note"><summary>Research context</summary><p>The original study describes benchmarking Intuit, TaxDome, Canopy and Sanford Tax, followed by high-fidelity testing and a CPA beta group. Participant counts, interview dates and anonymized observations still need to be added. The consultant's domain mapping was a team input, distinct from my interface and prototype work.</p></details></section>
<section class="invoice-chapter" id="decisions"><p class="eyebrow">03 / THE DESIGN REASONING</p><h2>Automate the repetitive. Support the expert.</h2>{decisions()}</section>
{figure('dashboard', 'Original TaxOS interface: the CPA workspace and preparation experience.')}
<section class="invoice-chapter" id="prototype"><p class="eyebrow">04 / BEYOND STATIC SCREENS</p><h2>Make the workflow tangible.</h2><p class="chapter-copy">I translated Figma designs into a functional prototype, using Claude Code for backend logic, GitHub for version control and Vercel for deployment. Mock tax data let CPAs try the flow before production development.</p><div class="iteration-plan"><article><h3>Design</h3><p>Shape the workspace and client intake in Figma.</p></article><article><h3>Prototype</h3><p>Connect screens with working logic and mock tax data.</p></article><article><h3>Learn</h3><p>Test with CPAs and carry feedback into the next version.</p></article></div><p class="evidence-pending">Prototype work demonstrates interaction and workflow exploration; it does not establish the accuracy of AI-generated tax information.</p></section>
{figure('workflow', 'Original TaxOS design artifact: a closer look at the product workflow.')}
<section class="invoice-chapter" id="iteration"><p class="eyebrow">05 / ITERATION</p><h2>From a prototype to a second version.</h2><div class="iteration-plan"><article><h3>Discovery &amp; testing</h3><p>Market research, domain mapping and high-fidelity exploration established the initial direction.</p></article><article><h3>V1 &amp; beta</h3><p>Development and testing involved the CPA network recruited during discovery.</p></article><article><h3>V2 &amp; launch</h3><p>The next version refined the dynamic questionnaire and bulk document matching before commercial launch.</p></article></div><details class="evidence-note"><summary>The next detail to document</summary><p>The earlier case study attributes these refinements to prototype feedback, but does not show a specific observation, before-and-after revision or retest result. Add that chain of evidence to show precisely how a CPA's feedback changed the design.</p></details><p class="chapter-copy">A proposed next evaluation: observe how CPAs detect and correct a mismatched document or uncertain extraction. Measure correction effort alongside preparation speed.</p></section>
<section class="invoice-chapter" id="outcomes"><p class="eyebrow">06 / OUTCOMES</p><h2>A product launched. A clearer workflow.</h2><p class="chapter-copy">TaxOS launched as a revenue-generating SaaS product, according to the original case study. The design connects three previously scattered parts of preparation.</p><div class="outcome-strip"><span>Client intake</span><b aria-hidden="true">+</b><span>Document collection</span><b aria-hidden="true">+</b><span>Workpapers</span></div><details class="evidence-note"><summary>Explore reported results and measurement context</summary><div class="metric-table-wrap"><table class="metric-review"><thead><tr><th>Reported result</th><th>Context still needed</th></tr></thead><tbody><tr><td>Checklist creation: 2–3 hours → 20 seconds</td><td>Define whether this compares checklist generation alone or the complete preparation and CPA review task. Add sample size and timing method.</td></tr><tr><td>Document collection cycle: 50% shorter</td><td>Add comparable cohorts, start/end events and measurement periods.</td></tr><tr><td>20+ paying B2B customers after V2</td><td>Add the reporting date, customer definition and commercial source. This is a team outcome, not sole design attribution.</td></tr></tbody></table></div></details><p class="evidence-pending">Reported in the original portfolio · measurement context pending.</p><p class="chapter-copy">My takeaway: the useful role for AI begins with a clear workflow. Faster generation only helps when the next person can understand, review and act on the result.</p></section>
<section class="next-project"><div><p class="eyebrow">[next story]</p><h2 class="handwritten">{e(next_project['title'])}</h2></div><a class="button button-yellow" href="/projects/{e(next_project['slug'])}">Next case study ↗</a></section>{contact_cta()}'''
    return render(project['case_title'], project['summary'], content, 'work', 'case-page invoice-case taxos-case')
